1	import { createContext, createElement, type ReactNode, useContext, useState } from "react";
2	import {
3	  type Asset,
4	  type Incident,
5	  assets as initialAssets,
6	  incidents as initialIncidents,
7	  jobs as initialJobs,
8	  type Job,
9	} from "../data/mock";
10	
11	type Role = "ops" | "supervisor" | "tech";
12	
13	interface AppState {
14	  role: Role;
15	  setRole: (r: Role) => void;
16	  assets: Asset[];
17	  incidents: Incident[];
18	  jobs: Job[];
19	  activeIncidentId: string | null;
