// Quick sanity check of model logic
// Simulate what sentinel does with chiller-a-03 telemetry
const telemetry = [
  { metric: "CHW Supply Temp", value: 11.2, unit: "°C", trend: "up" },
  { metric: "Flow Rate", value: 89, unit: "GPM", trend: "down" },
  { metric: "Compressor Load", value: 97, unit: "%", trend: "up" },
];

const BASELINES = {
  "CHW Supply Temp": { mean: 7.0, std: 1.0, threshold: 12.0 },
  "Compressor Load": { mean: 70, std: 10, threshold: 95 },
  "Flow Rate": { mean: 145, std: 15, threshold: 80 },
};
const ABOVE_IS_BAD = { "CHW Supply Temp": true, "Compressor Load": true, "Flow Rate": false };

let maxSigma = 0, anomalousCount = 0;
for (const t of telemetry) {
  const bl = BASELINES[t.metric];
  const aboveBad = ABOVE_IS_BAD[t.metric];
  if (!bl) continue;
  const rawSigma = (t.value - bl.mean) / bl.std;
  const absSigma = Math.abs(rawSigma);
  const isBad = aboveBad ? rawSigma > 1.5 : rawSigma < -1.5;
  if (isBad && absSigma > maxSigma) { maxSigma = absSigma; }
  if (isBad) anomalousCount++;
  console.log(`${t.metric}: sigma=${rawSigma.toFixed(2)}, isBad=${isBad}`);
}

const compLoad = 97;
let rate = compLoad >= 96 ? 0.045 : 0.025;
const gap = 12.0 - 11.2;
const ttf = Math.max(5, Math.round(gap / rate));
const confidence = Math.min(0.98, 0.60 + (anomalousCount / 3) * 0.34);

console.log(`\nmax sigma: ${maxSigma.toFixed(2)}`);
console.log(`TTF (q50): ${ttf} min`);
console.log(`confidence: ${confidence.toFixed(2)}`);

// Triton
const q50rate = 0.045, q95rate = 0.070;
const q50breach = Math.round(0.8 / q50rate);
const q95breach = Math.round(0.8 / q95rate);
console.log(`\nTriton: q50 breach in ${q50breach}m, q95 breach in ${q95breach}m`);
EOF

