// Simulate Hephaestus on chiller-a-03
const dependsOn = {
  "pump-chw-03": ["chiller-a-03"],
  "pump-chw-04": ["chiller-a-03"],
  "crah-b-01": ["chiller-a-03", "pump-chw-03"],
  "crah-b-02": ["chiller-a-03", "pump-chw-03"],
  "crah-b-03": ["chiller-a-03", "pump-chw-04"],
  "crah-b-04": ["chiller-a-03", "pump-chw-04"],
  "pod-04": ["crah-b-01", "pdu-c"],
  "pod-05": ["crah-b-02", "pdu-c"],
  "pod-06": ["crah-b-03", "pdu-d"],
  "rack-c01": ["crah-b-04", "pdu-c"],
};

// Build reverse map
const dependents = new Map();
for (const [id, deps] of Object.entries(dependsOn)) {
  for (const dep of deps) {
    if (!dependents.has(dep)) dependents.set(dep, []);
    dependents.get(dep).push(id);
  }
}

const sourceId = "chiller-a-03";
const visited = new Set([sourceId]);
const queue = [{ id: sourceId, depth: 0 }];
const blastRadius = [], cascadeDelays = {};
let pumpCount = 0, crahCount = 0, computeCount = 0;

while (queue.length > 0) {
  const { id, depth } = queue.shift();
  for (const childId of dependents.get(id) ?? []) {
    if (visited.has(childId)) continue;
    visited.add(childId);
    let delay;
    if (childId.includes("pump")) { delay = 4 + pumpCount * 2; pumpCount++; }
    else if (childId.startsWith("crah-b")) { delay = 11 + crahCount; crahCount++; }
    else if (childId.startsWith("pod") || childId.startsWith("rack")) { delay = 18 + computeCount * 2; computeCount++; }
    else { delay = (depth + 1) * 6; }
    cascadeDelays[childId] = delay;
    blastRadius.push({ id: childId, delay });
    queue.push({ id: childId, depth: depth + 1 });
  }
}

const sorted = [...blastRadius].sort((a, b) => a.delay - b.delay).map(x => x.id);
console.log("Blast radius (sorted):", sorted);
console.log("Cascade delays:", cascadeDelays);
EOF

